on_id" AS "id", "node_revision__layout_builder__layout"."langcode" AS "langcode", "node_revision__layout_builder__layout"."delta" AS "delta" FROM "node_revision__layout_builder__layout" "node_revision__layout_builder__layout" WHERE ("node_revision__layout_builder__layout"."revision_id" IN ("75")) AND ("node_revision__layout_builder__layout"."deleted" = 0)) "delta_join" LEFT OUTER JOIN "node_revision__field_ingredients" "node_revision__field_ingredients" ON "node_revision__field_ingredients"."revision_id" = "delta_join"."id" AND "node_revision__field_ingredients"."langcode" = "delta_join"."langcode" AND "node_revision__field_ingredients"."delta" = "delta_join"."delta" AND "node_revision__field_ingredients"."deleted" = 0 LEFT OUTER JOIN "node_revision__field_recipe_category" "node_revision__field_recipe_category" ON "node_revision__field_recipe_category"."revision_id" = "delta_join"."id" AND "node_revision__field_recipe_category"."langcode" = "delta_join"."langcode" AND "node_revision__field_recipe_category"."delta" = "delta_join"."delta" AND "node_revision__field_recipe_category"."deleted" = 0 LEFT OUTER JOIN "node_revision__field_tags" "node_revision__field_tags" ON "node_revision__field_tags"."revision_id" = "delta_join"."id" AND "node_revision__field_tags"."langcode" = "delta_join"."langcode" AND "node_revision__field_tags"."delta" = "delta_join"."delta" AND "node_revision__field_tags"."deleted" = 0 LEFT OUTER JOIN "node_revision__layout_builder__layout" "node_revision__layout_builder__layout" ON "node_revision__layout_builder__layout"."revision_id" = "delta_join"."id" AND "node_revision__layout_builder__layout"."langcode" = "delta_join"."langcode" AND "node_revision__layout_builder__layout"."delta" = "delta_join"."delta" AND "node_revision__layout_builder__layout"."deleted" = 0 INNER JOIN "node_field_revision" "base" ON "base"."vid" = "delta_join"."id" AND "base"."langcode" = "delta_join"."langcode" ORDER BY "delta_join"."delta" ASC
